		sections={
			{id=21559,title="Overview",body="Sludgefist gains rage as the battle ensues. At 100 rage Sludgefist starts a |cFF2959D3|Hspell:331212|h[Heedless Charge]|h|r toward the player affected by |cFF2959D3|Hspell:331209|h[Hateful Gaze]|h|r.\n\nSludgefist triggers |cFF2959D3|Hspell:332197|h[Collapsing Foundation]|h|r if he impacts a wall while charging."},
			{id=21560,title="Tank",body="$bullet;Sludgefist hits two targets at once with |cFF2959D3|Hspell:335297|h[Giant Fists]|h|r.\n$bullet;Sludgefist triggers |cFF2959D3|Hspell:332197|h[Collapsing Foundation]|h|r if he impacts a wall during |cFF2959D3|Hspell:331212|h[Heedless Charge]|h|r.\n$[16$bullet;Moving too far from an ally while affected with |cFF2959D3|Hspell:335300|h[Chain Link]|h|r will trigger |cFF2959D3|Hspell:335295|h[Shattering Chain]|h|r.$]"},
			{id=21561,title="Healer",body="$bullet;|cFF2959D3|Hspell:332443|h[Collapsing Foundation]|h|r inflicts increasing damage to all players as the battle continues.\n$[14,15,16$bullet;Moving too far from an ally while affected with |cFF2959D3|Hspell:335300|h[Chain Link]|h|r will trigger |cFF2959D3|Hspell:335295|h[Shattering Chain]|h|r.$]"},
			{id=21562,title="Damage",body="$bullet;Sludgefist inflicts massive damage to any player caught in the path of |cFF2959D3|Hspell:331212|h[Heedless Charge]|h|r.\n$[14,15,16$bullet;Moving too far from an ally while affected with |cFF2959D3|Hspell:335300|h[Chain Link]|h|r will trigger |cFF2959D3|Hspell:335295|h[Shattering Chain]|h|r.$]"},
