		sections={
			{id=21563,title="Overview",body="Periodically, Blightbone will |cFF2959D3|Hspell:320596|h[Heaving Retch]|h|r towards a player, spewing up Carrion Worms.  As Carrion Worms attack their target they grow larger, eventually exploding into a |cFF2959D3|Hspell:320631|h[Carrion Eruption]|h|r."},
			{id=21564,title="Tank",body="$bullet;Avoid |cFF2959D3|Hspell:320596|h[Heaving Retch]|h|r.\n$bullet;|cFF2959D3|Hspell:320637|h[Fetid Gas]|h|r pacifies and silences all players standing within it.\n$bullet;|cFF2959D3|Hspell:320655|h[Crunch]|h|r inflicts heavy damage to Blightbone's current target."},
			{id=21566,title="Damage Dealers",body="$bullet;Position |cFF2959D3|Hspell:320596|h[Heaving Retch]|h|r to avoid hitting other players.\n$bullet;Carrion Worms cast |cFF2959D3|Hspell:320614|h[Blood Gorge]|h|r instead of melee attacking, eventually exploding in a |cFF2959D3|Hspell:320631|h[Carrion Eruption]|h|r."},
			{id=21565,title="Healer",body="$bullet;Position |cFF2959D3|Hspell:320596|h[Heaving Retch]|h|r to avoid hitting other players.\n$bullet;Carrion Worms cast |cFF2959D3|Hspell:320614|h[Blood Gorge]|h|r instead of melee attacking, eventually exploding in a |cFF2959D3|Hspell:320631|h[Carrion Eruption]|h|r."},
			{id=21571,title="Section 5"},
			{id=30276,title="Carrion Worm",body="Carrion Worms hunger for blood, searching out random players to feast upon.\n$[!23\n\nIn Mythic difficulty, Carrion Worms now erupt into a pool of Fetid Gas upon dying.$]",difficultyIDs={1,2,23,24}},
