		sections={
			{id=21577,title="Overview",body="Defeat all three challengers to prove your worth.  Each challenger unleashes a powerful ability when they reach 100 energy."},
			{id=22650,title="Tank",body="$bullet;|cFF2959D3|Hspell:320069|h[Mortal Strike]|h|r is used when Dessia reaches 100 energy.\n$bullet;When Dessia |cFF2959D3|Hspell:324085|h[Enrages]|h|r, she will fixate on targets at random.",difficultyIDs={1,2}},
			{id=22652,title="Damage Dealers",body="$bullet;When Dessia |cFF2959D3|Hspell:324085|h[Enrages]|h|r, she will fixate on targets at random.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.\n$bullet;When Sathel the Accursed uses |cFF2959D3|Hspell:320293|h[One with Death]|h|r, she is immune to interrupt effects until the shield is broken.",difficultyIDs={1,2}},
			{id=22651,title="Healer",body="$bullet;|cFF2959D3|Hspell:320069|h[Mortal Strike]|h|r reduces all healing taken.\n$bullet;|cFF2959D3|Hspell:320248|h[Genetic Alteration]|h|r lasts until dispelled.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.",difficultyIDs={1,2}},
			{id=21578,title="Tank",body="$bullet;|cFF2959D3|Hspell:320069|h[Mortal Strike]|h|r is used when Dessia reaches 100 energy.\n$bullet;When Dessia |cFF2959D3|Hspell:324085|h[Enrages]|h|r, she will fixate on targets at random.\n$bullet;Xira the Underhanded will periodically sneak up on a player and use her |cFF2959D3|Hspell:333540|h[Opportunity Strikes]|h|r on them.",difficultyIDs={8,23}},
			{id=21580,title="Damage Dealers",body="$bullet;When Dessia |cFF2959D3|Hspell:324085|h[Enrages]|h|r, she will fixate on targets at random.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.\n$bullet;When Sathel the Accursed uses |cFF2959D3|Hspell:320293|h[One with Death]|h|r, she is immune to interrupt effects until the shield is broken.\n$bullet;Xira the Underhanded will periodically sneak up on a player and use her |cFF2959D3|Hspell:333540|h[Opportunity Strikes]|h|r on them.",difficultyIDs={8,23}},
			{id=21579,title="Healer",body="$bullet;|cFF2959D3|Hspell:320069|h[Mortal Strike]|h|r reduces all healing taken.\n$bullet;|cFF2959D3|Hspell:320248|h[Genetic Alteration]|h|r lasts until dispelled.\n$bullet;|cFF2959D3|Hspell:333292|h[Searing Death]|h|r inflicts damage to nearby allies.\n$bullet;Xira the Underhanded will periodically sneak up on a player and use her |cFF2959D3|Hspell:333540|h[Opportunity Strikes]|h|r on them.",difficultyIDs={8,23}},
			{id=31257,title="Section 21",difficultyIDs={8,23}},
