		sections={
			{id=21633,title="Overview",body="Kin-Tara and her companion, Azules defend the rear of the Forsworn forces.  Kin-Tara will periodically take to the air and unleash |cFF2959D3|Hspell:321009|h[Charged Spears]|h|r before returning to the ground to resume her assault.  When either Azule or Kin-Tara are slain, the remaining companion |cFF2959D3|Hspell:323828|h[Enrages]|h|r, unlocking new abilities."},
			{id=21634,title="Tank",body="$bullet;Kin-Tara uses |cFF2959D3|Hspell:320966|h[Overhead Slash]|h|r at 100 energy, inflicting a large amount of damage to her primary target.\n$bullet;|cFF2959D3|Hspell:321009|h[Charged Spear]|h|r inflicts a high amount of damage to all players near the impact."},
			{id=21636,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:321009|h[Charged Spear]|h|r inflicts a high amount of damage to all players near the impact."},
			{id=21635,title="Healer",body="$bullet;Kin-Tara uses |cFF2959D3|Hspell:320966|h[Overhead Slash]|h|r at 100 energy, inflicting a large amount of damage to all players in front of her.\n$bullet;|cFF2959D3|Hspell:321009|h[Charged Spear]|h|r inflicts a high amount of damage to all players near the impact."},
