		sections={
			{id=21700,title="Overview",body="At health thresholds of 66% and 33%, Doctor Ickus empowers his jetpack and leaps away from the players towards a random slime pool. Once there, he sets a bomb that will detonate, causing a |cFF2959D3|Hspell:321406 |h[Virulent Explosion]|h|r.",difficultyIDs={1,2}},
			{id=21702,title="Tank",body="$bullet;Pestilence Slimes grant Doctor Ickus |cFF2959D3|Hspell:331967 |h[Rapid Infection]|h|r when close.\n$bullet;Step on Erupting Oozes before they |cFF2959D3|Hspell:341444 |h[Erupt]|h|r.",difficultyIDs={1,2}},
			{id=22512,title="Tank",body="$bullet;Pestilence Slimes grant Doctor Ickus |cFF2959D3|Hspell:331967 |h[Rapid Infection]|h|r when close.\n$bullet;Congealed Slimes grant Doctor Ickus |cFF2959D3|Hspell:333737 |h[Congealed Contagion]|h|r when close.\n$bullet;Step on Erupting Oozes before they |cFF2959D3|Hspell:341444 |h[Erupt]|h|r.",difficultyIDs={8,23}},
			{id=21701,title="Damage Dealers",body="$bullet;Defeat Plague Bombs before they cast |cFF2959D3|Hspell:321406 |h[Virulent Explosion]|h|r.\n$bullet;On death, Pestilence Slimes melt into pools of |cFF2959D3|Hspell:321976 |h[Rapid Infection]|h|r.",difficultyIDs={1,2}},
			{id=22511,title="Damage Dealers",body="$bullet;Defeat Plague Bombs before they cast |cFF2959D3|Hspell:321406 |h[Virulent Explosion]|h|r.\n$bullet;On death, Pestilence Slimes melt into pools of |cFF2959D3|Hspell:321976 |h[Rapid Infection]|h|r.\n$bullet;Congealed Slimes grant Doctor Ickus |cFF2959D3|Hspell:333737 |h[Congealed Contagion]|h|r when close.",difficultyIDs={8,23}},
