		sections={
			{id=21754,title="Overview",body="Halkias, the Sin-Stained Goliath leaves fields of |cFF2959D3|Hspell:323001|h[Glass Shards]|h|r in his destructive wake.  He is able to focus the lights of Revendreth into beams of |cFF2959D3|Hspell:322913|h[Refracted Sinlight]|h|r."},
			{id=21755,title="Tank",body="$bullet; |cFF2959D3|Hspell:322936|h[Crumbling Slam]|h|r inflicts massive damage to all players near Halkias' target.\n$bullet; Dodge |cFF2959D3|Hspell:322913|h[Refracted Sinlight]|h|r and beware Halkias changing directions."},
			{id=21757,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:322943|h[Heave Debris]|h|r inflicts massive damage to players in the impact area.\n$bullet; Dodge |cFF2959D3|Hspell:322913|h[Refracted Sinlight]|h|r and beware Halkias changing directions."},
			{id=21756,title="Healer",body="$bullet; |cFF2959D3|Hspell:322943|h[Heave Debris]|h|r and |cFF2959D3|Hspell:322936|h[Crumbling Slam]|h|r both inflict moderate group damage upon impact.\n$bullet; Dodge |cFF2959D3|Hspell:322913|h[Refracted Sinlight]|h|r and beware Halkias changing directions."},
