		sections={
			{id=21789,title="Overview",body="Hakkar utilizes |cFF2959D3|Hspell:322773|h[Blood Barrier]|h|r to protect himself from attacks then lashes out with a devastating |cFF2959D3|Hspell:323064|h[Blood Barrage]|h|r. Hakkar's Atal'ai priests also rally to his aid, becoming Sons of Hakkar throughout the encounter."},
			{id=21791,title="Tank",body="$bullet; Defeat Sons of Hakkar and mitigate damage from |cFF2959D3|Hspell:322773|h[Blood Barrier]|h|r to reduce the magnitude of the absorb shield.\n$bullet; Sons of Hakkar create |cFF2959D3|Hspell:323569|h[Spilled Essence]|h|r when reaching 0 health.\n$bullet; Utilize defensive abilities for |cFF2959D3|Hspell:322736|h[Piercing Barb]|h|r."},
			{id=21790,title="Damage Dealers",body="$bullet; Defeat Sons of Hakkar and mitigate damage from |cFF2959D3|Hspell:322773|h[Blood Barrier]|h|r to reduce the magnitude of the absorb shield.\n$bullet; Consider positioning when afflicted with |cFF2959D3|Hspell:322746|h[Corrupted Blood]|h|r.\n$bullet; Assist party members affected by |cFF2959D3|Hspell:328987|h[Zealous]|h|r."},
			{id=21792,title="Healer",body="$bullet; Help mitigate damage from |cFF2959D3|Hspell:322773|h[Blood Barrier]|h|r to reduce the magnitude of the absorb shield.\n$bullet; Consider positioning when afflicted with |cFF2959D3|Hspell:322746|h[Corrupted Blood]|h|r."},
			{id=21793,title="Hakkar the Soulflayer"},
