			{id=21796,title="Tank",body="$bullet; Intercept beams of energy from Millhouse's |cFF2959D3|Hspell:320786|h[Power Overwhelming]|h|r to deny Millhouse and gain temporary power, at a cost.\n$bullet; Dismantle Millificent's |cFF2959D3|Hspell:320811|h[Experimental Squirrel Bomb]|h|r to reduce party damage taken.\n$bullet; Millificent's |cFF2959D3|Hspell:320144|h[Buzz-Saw]|h|r inflicts physical damage and leaves a damage-over-time effect, |cFF2959D3|Hspell:320147|h[Bleeding]|h|r."},
			{id=22170,title="Damage Dealers",body="$bullet; Intercept beams of energy from Millhouse's |cFF2959D3|Hspell:320786|h[Power Overwhelming]|h|r to deny Millhouse and gain temporary power, at a cost.\n$bullet; Dismantle Millificent's |cFF2959D3|Hspell:320811|h[Experimental Squirrel Bomb]|h|r to reduce party damage taken.",difficultyIDs={1,2}},
			{id=21795,title="Damage Dealers",body="$bullet; Intercept beams of energy from Millhouse's |cFF2959D3|Hspell:320786|h[Power Overwhelming]|h|r to deny Millhouse and gain temporary power, at a cost.\n$bullet; Dismantle Millificent's |cFF2959D3|Hspell:320811|h[Experimental Squirrel Bomb]|h|r to reduce party damage taken.\n$bullet; Manuver to affect the current boss when targeted by Millificent's |cFF2959D3|Hspell:324047|h[Echo Finger Laser X-treme]|h|r or Millhouse's |cFF2959D3|Hspell:320132|h[Shadowfury]|h|r.",difficultyIDs={8,23}},
			{id=22171,title="Healer",body="$bullet; Intercept beams of energy from Millhouse's |cFF2959D3|Hspell:320786|h[Power Overwhelming]|h|r to deny Millhouse and gain temporary power, at a cost.\n$bullet; Millificent's |cFF2959D3|Hspell:320145|h[Buzz-Saw]|h|r and |cFF2959D3|Hspell:320168|h[Thrown Buzz-Saw]|h|r's damage-over-time effect, |cFF2959D3|Hspell:320147|h[Bleeding]|h|r, can be intense when multiple stacks are present.",difficultyIDs={1,2}},
			{id=21797,title="Healer",body="$bullet; Intercept beams of energy from Millhouse's |cFF2959D3|Hspell:320786|h[Power Overwhelming]|h|r to deny Millhouse and gain temporary power, at a cost.\n$bullet; Millificent's |cFF2959D3|Hspell:320145|h[Buzz-Saw]|h|r and |cFF2959D3|Hspell:320168|h[Thrown Buzz-Saw]|h|r's damage-over-time effect, |cFF2959D3|Hspell:320147|h[Bleeding]|h|r, can be intense when multiple stacks are present.\n$bullet; Manuver to affect the current boss when targeted by Millificent's |cFF2959D3|Hspell:324047|h[Echo Finger Laser X-treme]|h|r or Millhouse's |cFF2959D3|Hspell:320132|h[Shadowfury]|h|r.",difficultyIDs={8,23}},
			{id=22026,title="Stage One: Millhouse's Magics",body="\"I'm going to light you up, sweet cheeks!\"\n\nMillhouse steps into the arena, while Millificent takes purchase on the outer railing, assisting her arcane beloved."},
