	[2410]={
		encounterID=2410,
		instanceID=1188,
		order=4,
		name="Mueh'zala",
		lore="Father of Sleep, Son of Time, the Night's Friend, Mueh'zala ushered the dead of Azeroth long before Bwonsamdi made his first deal. He knows a god should rule, not beg for servants and worshipers. The plans he laid in ancient times to reclaim that power are coming to fruition, once he deals with his rebellious replacement.",
		dungeonEncounterID=2396,
		uiMapID=1680,
		pin={x=0.508,y=0.5776},
		difficultyIDs={1,2,8,23,24,236},
		npcIDs={166018,166608,254254},
