		sections={
			{id=21807,title="Overview",body="High Adjudicator Aleez commands the congregation of souls in the Halls of Atonement. The High Adjudicator periodically summons forth a Ghastly Parishioner to move towards a random player.  These parishioners are immune to damage and emit a |cFF2959D3|Hspell:323852|h[Pulse from Beyond]|h|r until they can be sealed within a |cFF2959D3|Hspell:323848|h[Vessels of Atonement]|h|r."},
			{id=21808,title="Tank",body="$bullet; Ghastly Parishioners emit a |cFF2959D3|Hspell:323852|h[Pulse from Beyond]|h|r until they are sealed within a |cFF2959D3|Hspell:323848|h[Vessels of Atonement]|h|r\n$bullet; |cFF2959D3|Hspell:323538|h[Anima Bolt]|h|r inflicts heavy damage."},
			{id=21810,title="Damage Dealers",body="$bullet; Ghastly Parishioners emit a |cFF2959D3|Hspell:323852|h[Pulse from Beyond]|h|r until they are sealed within a |cFF2959D3|Hspell:323848|h[Vessels of Atonement]|h|r\n$bullet; |cFF2959D3|Hspell:329340|h[Anima Fountain]|h|r inflicts heavy damage to players in the impact area."},
			{id=21809,title="Healer",body="$bullet; Ghastly Parishioners emit a |cFF2959D3|Hspell:323852|h[Pulse from Beyond]|h|r until they are sealed within a |cFF2959D3|Hspell:323848|h[Vessels of Atonement]|h|r\n$bullet; |cFF2959D3|Hspell:1236512|h[Unstable Anima]|h|r inflicts moderate damage to afflicted players until it is removed."},
