	[2412]={
		encounterID=2412,
		instanceID=1186,
		order=4,
		name="Devos, Paragon of Doubt",
		lore="Devos was the very symbol of loyalty until a soul with a troubling past arrived in Bastion. Her doubt overwhelmed her until she fell into open rebellion, aided by the darkest powers of the Shadowlands. Seizing the Spires of Ascension is just the first step, and the destruction of the Archon is now within her grasp.",
		dungeonEncounterID=2359,
		uiMapID=1695,
		pin={x=0.4559,y=0.6289},
		difficultyIDs={1,2,8,23,24},
		npcIDs={162061,167169},
		displayIDs={95665},
		loot={
