		sections={
			{id=21841,title="Overview",body="Lord Chamberlain commands powerful telekinetic powers to hurl Sinstone Statues around the battlefield. At 70% and 40% health, Lord Chamberlain will cast |cFF2959D3|Hspell:341245|h[Chamberlain's Chorus]|h|r."},
			{id=21844,title="Tank",body="$bullet;Position yourself between Lord Chamberlain and a Sinstone Statue to intercept missiles during |cFF2959D3|Hspell:323393|h[Ritual of Woe]|h|r to reduce party wide damage.\n$bullet;|cFF2959D3|Hspell:323437|h[Stigma of Pride]|h|r causes increased damage the longer it lasts."},
			{id=21842,title="Damage Dealers",body="$bullet;Position yourself between Lord Chamberlain and a Sinstone Statue to intercept missiles during |cFF2959D3|Hspell:323393|h[Ritual of Woe]|h|r to reduce party wide damage.\n$bullet; |cFF2959D3|Hspell:1236964|h[Erupting Torment]|h|r inflicts massive damage to players near Lord Chamberlain or sinstone statues."},
			{id=21843,title="Healer",body="$bullet;Position yourself between Lord Chamberlain and a Sinstone Statue to intercept missiles during |cFF2959D3|Hspell:323393|h[Ritual of Woe]|h|r to reduce party wide damage.\n$bullet; Sinstone Statues inflict moderate group damage to all players when thrown with |cFF2959D3|Hspell:1237634|h[Telekinetic Toss]|h|r."},
