	[2414]={
		encounterID=2414,
		instanceID=1186,
		order=3,
		name="Oryphrion",
		lore="Oryphrion is the firepower in the Paragon of Loyalty's vanguard. The Dark Colossus has dominated the invasion into the city with their Anima fueled artillery, and now fiercely defends the font of power before the Archon's seat.",
		dungeonEncounterID=2358,
		uiMapID=1694,
		pin={x=0.5309,y=0.3829},
		difficultyIDs={1,2,8,23,24},
		npcIDs={175306},
		displayIDs={93502},
		loot={
			{itemID=180118,diffs={},faction=-1},
