			{itemID=182471,diffs={1,2,23},faction=-1},
			{itemID=182753,diffs={1,2,23},faction=-1},
			{itemID=180944,diffs={1,2,23},faction=-1},
			{itemID=182187,diffs={1,2,23},faction=-1},
			{itemID=183313,diffs={1,2,23},faction=-1},
			{itemID=183392,diffs={1,2,23},faction=-1},
			{itemID=183469,diffs={1,2,23},faction=-1},
			{itemID=187507,diffs={1,2,23},faction=-1},
			{itemID=182476,diffs={1,2,23},faction=-1},
		},
		sections={
			{id=21865,title="Overview",body="Oryphrion spends anima to fuel their attacks. Standing in an |cFF2959D3|Hspell:324392|h[Anima Field]|h|r will empower Oryphrion and remove the anima cost of abilities.\n\nOnce Oryphrion hits 0 anima, they become |cFF2959D3|Hspell:323878|h[Drained]|h|r and will then |cFF2959D3|Hspell:324046|h[Recharge Anima]|h|r."},
			{id=21866,title="Tank",body="$bullet;|cFF2959D3|Hspell:324392|h[Anima Fields]|h|r created by |cFF2959D3|Hspell:324444|h[Empyreal Ordnance]|h|r empower Oryphrion.\n$bullet;|cFF2959D3|Hspell:324608|h[Charged Stomp]|h|r inflicts heavy Arcane damage in an area and reduces player movement speed."},
			{id=21868,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:323072|h[Purifying Blast]|h|r inflicts damage to nearby allies.\n$bullet;|cFF2959D3|Hspell:324392|h[Anima Fields]|h|r created by |cFF2959D3|Hspell:324444|h[Empyreal Ordnance]|h|r empower Oryphrion."},
			{id=21867,title="Healer",body="$bullet;|cFF2959D3|Hspell:324608|h[Charged Stomp]|h|r inflicts heavy Arcane damage in an area and reduces player movement speed.\n$bullet;|cFF2959D3|Hspell:323072|h[Purifying Blast]|h|r inflicts damage to nearby allies.\n$bullet;|cFF2959D3|Hspell:324392|h[Anima Fields]|h|r created by |cFF2959D3|Hspell:324444|h[Empyreal Ordnance]|h|r empower Oryphrion."},
			{id=21931,title="Drained"},
			{id=21932,title="Recharge Anima"},
			{id=22580,title="Coalesced Anima",body="Coalesced Anima moves back towards Oryphrion, causing Overcharged Anima if they reach Oryphrion."},
			{id=21933,title="Anima Surge",difficultyIDs={1,2}},
			{id=22581,title="Anima Surge",difficultyIDs={8,23}},
			{id=22023,title="Overcharge Anima"},
			{id=21927,title="Empyreal Ordnance"},
			{id=21928,title="Anima Field",body="The Anima Field reduces the Haste of players within it by $323792s2% and inflicts $323792s1 Arcane damage every 1.5 sec. \n\nWhile Oryphrion remains in an Anima Field, the anima cost for their abilities is removed and their damage done is increased by $324392s1%."},
			{id=21929,title="Purifying Blast"},
