			{id=22371,title="Charged Anima",difficultyIDs={1,2}},
			{id=22579,title="Charged Anima",difficultyIDs={8,23}},
		},
	},
	[2415]={
		encounterID=2415,
		instanceID=1189,
		order=2,
		name="Executor Tarvold",
		lore="Many venthyr consider the torment of their charges and the extraction of sins and anima their sacred duty. The creature known as Executor Torvald being set as warden and  allowed to take its sick pleasure in torturing the prisoners here shows the depravity Revendreth has fallen to.",
		dungeonEncounterID=2361,
		uiMapID=1675,
		pin={x=0.4775,y=0.8601},
		difficultyIDs={1,2,8,23,24},
