			{itemID=183499,diffs={1,2,23},faction=-1},
			{itemID=182464,diffs={1,2,23},faction=-1},
		},
		sections={
			{id=21876,title="Overview",body="Periodically Executor Tarvold summons forth one of the multitude of manifestiations he has imprisioned.  These manifestations consume the latent anima from the surroundings, growing larger over time.  When they are slain they erupt into a pool of |cFF2959D3|Hspell:323551|h[Residue]|h|r."},
			{id=21877,title="Tank",body="$bullet;Fleeting Manifestations leave behind large pools of |cFF2959D3|Hspell:323551|h[Residue]|h|r upon death."},
			{id=21878,title="Damage Dealers",body="$bullet; Quickly kill Fleeting Manifestations.\n$bullet;|cFF2959D3|Hspell:322554|h[Castigate]|h|r inflicts heavy damage to players near the target."},
			{id=21879,title="Healer",body="$bullet; While Fleeting Manifesations are alive they inflict party-wide damage with |cFF2959D3|Hspell:323548|h[Growing Pride]|h|r.\n$bullet;|cFF2959D3|Hspell:322554|h[Castigate]|h|r inflicts heavy damage to players near the target."},
			{id=22078,title="Section 10",difficultyIDs={23}},
			{id=21880,title="Section 5"},
			{id=21891,title="Section 8"},
			{id=21883,title="Fleeting Manifestation",body="Fleeting Manifestations absorb latent anima, gaining energy over time.  Upon reaching 100 Energy the Fleeting Manifestation ertupts, creating pool of Residue."},
			{id=21916,title="Section 9"},
		},
	},
	[2416]={
		encounterID=2416,
		instanceID=1186,
		order=2,
		name="Ventunax",
		lore="Ventunax is one of the deadliest Forsworn constructs, originally designed to test the courage of kyrian aspirants. The Praetorian's movements are so quick she can seem to disappear before her enemies' eyes.",
		dungeonEncounterID=2356,
		uiMapID=1693,
		pin={x=0.6363,y=0.4485},
