		sections={
			{id=21920,title="Overview",body="At full energy, Globgrog will |cFF2959D3|Hspell:324459|h[Beckon Slime]|h|r, summoning nearby Slimy Morsels that slowly move towards him. When a Slimy Morsel reaches Globgrog, he will |cFF2959D3|Hspell:319780|h[Consume Slime]|h|r, restoring his health."},
			{id=21923,title="Tank",body="$bullet;Globgrog will |cFF2959D3|Hspell:319780|h[Consume Slime]|h|r if a Slimy Morsel reaches him.\n\n$bullet;|cFF2959D3|Hspell:324667|h[Slime Wave]|h|r inflicts high damage to players in a frontal cone."},
			{id=21921,title="Damage Dealers",body="$bullet;Globgrog will |cFF2959D3|Hspell:319780|h[Consume Slime]|h|r if a Slimy Morsel reaches him.\n\n$bullet;|cFF2959D3|Hspell:324667|h[Slime Wave]|h|r inflicts high damage to players in a frontal cone."},
			{id=21922,title="Healer",body="$bullet;|cFF2959D3|Hspell:324527|h[Plaguestomp]|h|r inflicts party-wide damage.\n\n$bullet;|cFF2959D3|Hspell:324667|h[Slime Wave]|h|r inflicts high damage to players in a frontal cone."},
			{id=22353,title="Section 4"},
			{id=21918,title="Section 2",body="$[!23\n\nIn Mythic difficulty, Globgrog also beckons a Slimy Smorgasbord.$]"},
			{id=21924,title="Section 5"},
			{id=21925,title="Section 6"},
			{id=21926,title="Section 10"},
		},
	},
	[2420]={
		encounterID=2420,
		instanceID=1190,
		order=6,
		name="Lady Inerva Darkvein",
		lore="Anima fuels the Shadowlands, and Lady Inerva Darkvein seeks to unlock its mysteries. Under Denathrius's tutelage, she has learned insidious secrets to turn against his enemies. She will strip anima from Nathria's invaders and use it to shape a dark new future.",
		dungeonEncounterID=2406,
		uiMapID=1744,
		pin={x=0.3636,y=0.443},
		difficultyIDs={14,15,16,17},
		npcIDs={167517},
		displayIDs={96806},
		loot={
			{itemID=183021,diffs={},faction=-1},
			{itemID=183037,diffs={},faction=-1},
			{itemID=183026,diffs={},faction=-1},
			{itemID=182985,diffs={},faction=-1},
			{itemID=183015,diffs={},faction=-1},
			{itemID=183218,diffs={},faction=-1},
			{itemID=183240,diffs={},faction=-1},
			{itemID=183889,diffs={},faction=-1},
			{itemID=184025,diffs={},faction=-1},
			{itemID=182317,diffs={},faction=-1},
			{itemID=181466,diffs={},faction=-1},
			{itemID=182449,diffs={},faction=-1},
			{itemID=183502,diffs={},faction=-1},
			{itemID=183464,diffs={},faction=-1},
			{itemID=182336,diffs={},faction=-1},
			{itemID=181841,diffs={},faction=-1},
			{itemID=181498,diffs={},faction=-1},
			{itemID=181826,diffs={},faction=-1},
			{itemID=182469,diffs={},faction=-1},
			{itemID=182111,diffs={},faction=-1},
			{itemID=180896,diffs={},faction=-1},
			{itemID=182143,diffs={},faction=-1},
			{itemID=183482,diffs={},faction=-1},
			{itemID=183510,diffs={},faction=-1},
			{itemID=181495,diffs={},faction=-1},
		},
		sections={
			{id=22127,title="Overview",body="Lady Inerva Darkvein's abilities are directly linked to the anima levels of the containers.  As they rise, the efficacy of her abilities increases. Players can lower the levels of the containers by using the anima release valves located around the playspace.  Allowing any container to reach capacity will trigger a |cFF2959D3|Hspell:325225|h[Container Breach]|h|r\n."},
			{id=22128,title="Tanks",body="$bullet;Lady Inerva Darkveins' |cFF2959D3|Hspell:325379|h[Expose Desires]|h|r will alter your responsibilities as it gains power.\n$bullet;Make sure to trigger |cFF2959D3|Hspell:325384|h[Change of Heart]|h|r away from your allies.\n$bullet;Allies with |cFF2959D3|Hspell:325908|h[Shared Cognition]|h|r will take damage based off the damage you take from |cFF2959D3|Hspell:341621|h[Expose Desires]|h|r."},
			{id=22129,title="Healers",body="$bullet;Allies with |cFF2959D3|Hspell:325908|h[Shared Cognition]|h|r will take damage based off the damage the tank takes from |cFF2959D3|Hspell:341621|h[Expose Desires]|h|r.\n$bullet;Sins of the Past summoned by |cFF2959D3|Hspell:325064|h[Sins and Suffering]|h|r constantly damage the nearest player until they are connected with the beams of |cFF2959D3|Hspell:324983|h[Shared Suffering]|h|r.\n$bullet;The raid continually suffers damage from |cFF2959D3|Hspell:325184|h[Loose Anima]|h|r in the chamber. This damage increases with each open container.\n$bullet;If any container reaches capacity, a |cFF2959D3|Hspell:325225|h[Container Breach]|h|r occurs."},
			{id=22130,title="Damage Dealers",body="$bullet;Sins of the Past summoned by |cFF2959D3|Hspell:325064|h[Sins and Suffering]|h|r constantly damage the nearest player until they are connected with the beams of |cFF2959D3|Hspell:324983|h[Shared Suffering]|h|r.\n$bullet;If any container reaches capacity, a |cFF2959D3|Hspell:325225|h[Container Breach]|h|r occurs.\n$bullet;|cFF2959D3|Hspell:325769|h[Bottled Anima]|h|r will trigger a burst of |cFF2959D3|Hspell:329618|h[Unleashed Volatility]|h|r if not caught.\n$bullet;When you have |cFF2959D3|Hspell:325908|h[Shared Cognition]|h|r, you take damage based off the damage the tank takes from |cFF2959D3|Hspell:341621|h[Expose Desires]|h|r."},
			{id=21973,title="Primal Anima Containers",body="Anima containers are placed around Lady Inerva Darkvein's balcony that gradually gather anima energy to empower each of her abilities. \n\nPlayers can interact with the containers to open them, and close them by interacting with them again.\n\nOpen containers vent their |cFF2959D3|Hspell:325184|h[Loose Anima]|h|r into the playspace.\n\nWhen any container reaches full capacity, a |cFF2959D3|Hspell:325225|h[Container Breach]|h|r occurs.  The breach continues to damage players until the anima level is reduced below capacity."},
			{id=22942,title="Section 60"},
			{id=21975,title="Section 3",body="$[!14,15,16,17,18\n\nThe damage of Loose Anima increases with each open Primal Anima Container.$]"},
			{id=21974,title="Section 2"},
			{id=22423,title="Zero-Sum Game",body="$[!16In Mythic Raid difficulty, the anima drained by opening a Primal Anima Container is transferred to all closed Primal Anima Containers .$]",difficultyIDs={16}},
			{id=22564,title="Focus Container",body="$[!14,15,16,17\n\nWhile focused, a Primal Anima Container cannot be opened by players.$]"},
			{id=22571,title="Container of Desire",body="The Container of Desire governs the power of Lady Inerva Darkvein's Expose Desires ability.\n\nAs the container increases in level, the power of Expose Desires increases.\n\nLady Inerva Darkvein uses these abilities when she reaches 100 energy."},
			{id=22573,title="Section 4",body="$[!16\n\nOn Mythic Raid difficulty, the target is attacked by two images of their |cFF2959D3|Hspell:335322|h[Hidden Desires]|h|r.$]"},
			{id=22590,title="Section 24",difficultyIDs={16}},
			{id=21976,title="Section 4",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Desire surpasses 33% capacity.$]$[!16\n\nOn Mythic Raid difficulty, the target is attacked by two images of their |cFF2959D3|Hspell:335322|h[Hidden Desires]|h|r.$]"},
			{id=22420,title="Section 24",difficultyIDs={16}},
			{id=22575,title="Section 7"},
			{id=22576,title="Section 40",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Desire surpasses 66% capacity.$]$[!16\n\nOn Mythic Raid difficulty, the target is attacked by two images of their |cFF2959D3|Hspell:335322|h[Hidden Desires]|h|r.$]"},
			{id=22591,title="Section 24",difficultyIDs={16}},
			{id=21979,title="Section 7"},
			{id=21978,title="Section 6"},
			{id=22592,title="Container of Bottled Anima",body="The Container of Bottled Anima governs the power of Lady Inerva Darkvein's Bottled Anima ability.\n\nAs the container increases in level, the power of Bottled Anima increases."},
			{id=22593,title="Bottled Anima"},
			{id=22594,title="Section 10"},
			{id=21981,title="Bottled Anima",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Bottled Anima surpasses 33% capacity.$]"},
			{id=21982,title="Section 10"},
			{id=22421,title="Section 8"},
			{id=22595,title="Bottled Anima",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Bottled Anima surpasses 66% capacity.$]"},
			{id=22596,title="Section 10"},
			{id=22597,title="Section 8"},
			{id=22599,title="Container of Sin",body="The Container of Sin governs the power of Lady Inerva Darkvein's Sins and Suffering ability.\n\nAs the container increases in level, the power of Sins and Suffering increases."},
			{id=22628,title="Simple Geometry",body="$[!16In Mythic Raid difficulty, Sins and Suffering summons an additional Sins of the Past. Players must link all four orbs with the three beams of |cFF2959D3|Hspell:324983|h[Shared Suffering]|h|r.$]",difficultyIDs={16}},
			{id=22600,title="Primal Anima Orbs",body="$[!14,15,16\n\nIf players fail to connect Sins of the Past before they expire, |cFF2959D3|Hspell:331527|h[Indemnification]|h|r occurs.$]"},
			{id=22601,title="Section 12",body="$[!17\n\nIn Raid Finder difficulty, victims are Silenced until they sever the connection of Shared Suffering by linking the Sins of the Past.$]"},
			{id=22602,title="Section 30",difficultyIDs={14,15,16}},
			{id=21983,title="Primal Anima Orbs",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Sin surpasses 33% capacity.$]$[!14,15,16\n\nIf players fail to connect Sins of the Past before they expire, |cFF2959D3|Hspell:331527|h[Indemnification]|h|r occurs.$]"},
			{id=21984,title="Section 12",body="$[!17\n\nIn Raid Finder difficulty, victims are Silenced until they sever the connection of Shared Suffering by linking the Sins of the Past.$]"},
			{id=22493,title="Section 30",difficultyIDs={14,15,16}},
			{id=22566,title="Section 31"},
			{id=22604,title="Primal Anima Orbs",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Sin surpasses 66% capacity.$]$[!14,15,16\n\nIf players fail to connect Sins of the Past before they expire, |cFF2959D3|Hspell:331527|h[Indemnification]|h|r occurs.$]"},
			{id=22605,title="Section 12",body="$[!17\n\nIn Raid Finder difficulty, victims are Silenced until they sever the connection of Shared Suffering by linking the Sins of the Past.$]"},
			{id=22606,title="Section 30",difficultyIDs={14,15,16}},
			{id=22607,title="Section 31"},
			{id=22567,title="Container of Concentrated Anima",body="The Container of Concentrated Anima governs the power of Lady Inerva Darkvein's Concentrated Anima ability.\n\nAs the container increases in level, the power of Concentrated Anima increases.\n\nEach cast of Concentrated Anima results in one Harnessed Specter. Any additional players chosen for this ability cause a Conjured Manifestation to appear."},
			{id=22608,title="Section 45"},
			{id=22609,title="Unleash"},
			{id=22610,title="Section 46",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Concentrated Anima surpasses 33% capacity.$]"},
			{id=22611,title="Unleash"},
			{id=22612,title="Section 51"},
			{id=22613,title="Section 47",body="$[!14,15,16,17\n\nLady Inerva Darkvein uses this ability when the Container of Concentrated Anima surpasses 66% capacity.$]"},
			{id=22614,title="Unleash"},
			{id=22615,title="Section 51"},
			{id=22616,title="Section 53"},
			{id=22618,title="Conjured Manifestation",body="Continually |cFF2959D3|Hspell:331550|h[Condemns]|h|r the raid."},
			{id=22619,title="Section 55"},
			{id=22617,title="Harnessed Specter",body="Harnessed Specters are sessile and will |cFF2959D3|Hspell:334017|h[Condemn]|h|r the raid if not engaged in melee combat."},
			{id=22620,title="Section 58"},
			{id=22621,title="Section 55"},
		},
	},
	[2421]={
