	[2422]={
		encounterID=2422,
		instanceID=1190,
		order=3,
		name="Sun King's Salvation",
		lore="In the sinister confines of Castle Nathria, souls are being tortured not to redeem their sins, but to amplify them. The prideful Prince Kael'thas has been burdened with the sins of others, and his pain and hatred are channeled to make him a powerful weapon. This has imperiled his soul like no other, and it must be saved--if only to keep it from being unleashed upon the Shadowlands.",
		dungeonEncounterID=2402,
		uiMapID=1746,
		pin={x=0.5294,y=0.7461},
		difficultyIDs={14,15,16,17},
		npcIDs={165759,165805,168973},
		displayIDs={94481,94482,94498,95921,95922,95923,96156,96609},
		loot={
			{itemID=183007,diffs={},faction=-1},
			{itemID=183025,diffs={},faction=-1},
			{itemID=182986,diffs={},faction=-1},
			{itemID=183033,diffs={},faction=-1},
			{itemID=182977,diffs={},faction=-1},
			{itemID=183893,diffs={},faction=-1},
			{itemID=183304,diffs={},faction=-1},
			{itemID=183277,diffs={},faction=-1},
			{itemID=184019,diffs={},faction=-1},
			{itemID=184018,diffs={},faction=-1},
			{itemID=184020,diffs={},faction=-1},
			{itemID=182307,diffs={},faction=-1},
			{itemID=182584,diffs={},faction=-1},
			{itemID=182316,diffs={},faction=-1},
			{itemID=180844,diffs={},faction=-1},
			{itemID=181975,diffs={},faction=-1},
			{itemID=182107,diffs={},faction=-1},
			{itemID=182736,diffs={},faction=-1},
			{itemID=182677,diffs={},faction=-1},
			{itemID=182471,diffs={},faction=-1},
			{itemID=181504,diffs={},faction=-1},
		},
		sections={
			{id=22236,title="Overview",body="Kael'thas starts in a weakened state and needs assistance to bring him back to full strength. However, Sire Denathrius's forces continue to pour in, determined to stop your attempts at redeeming Kael'thas's soul. \n\nUpon Kael'thas reaching $341241s1% and $341241s2% health, a Shade of Kael'thas manifests, suspending everyone's ability to heal Kael'thas. This Shade of Kael'thas enters the arena and engages the raid until it is defeated. Inflicting damage to the Shade of Kael'thas also heals Kael'thas himself."},
			{id=22237,title="Tanks",body="$bullet;Vile Occultist's |cFF2959D3|Hspell:328248|h[Door of Shadows]|h|r impair threat management on them, and Soul Infusers ignore player threat entirely.\n$bullet;Shade of Kael'thas's |cFF2959D3|Hspell:326455|h[Fiery Strike]|h|r inflicts applications of |cFF2959D3|Hspell:326456|h[Burning Remnants]|h|r."},
			{id=22238,title="Damage Dealers",body="$bullet;Assist allies to mitigate damage taken from |cFF2959D3|Hspell:325877|h[Ember Blast]|h|r.\n$bullet;Soul Infusers are susceptible to crowd control.\n$bullet;Move away from allies when targeted for |cFF2959D3|Hspell:341473|h[Crimson Flurry]|h|r."},
			{id=22239,title="Healers",body="$bullet;Interact with the Infuser's Orbs to gain |cFF2959D3|Hspell:326078|h[Infuser's Boon]|h|r.\n$bullet;Heal Essence Fonts cast |cFF2959D3|Hspell:329561|h[Essence Overflow]|h|r at full health, greatly healing Kael'thas.\n$bullet;Move away from allies when targeted for |cFF2959D3|Hspell:341473|h[Crimson Flurry]|h|r."},
			{id=21966,title="Shade of Kael'thas",body="A Shade of Kael'thas manifests upon Kael'thas reaching $341241s1% and $341241s2% health."},
			{id=21967,title="Section 25"},
			{id=22396,title="Section 46",difficultyIDs={16}},
			{id=22397,title="Section 47",difficultyIDs={16}},
			{id=22080,title="Section 28",body="$[\n\n|cFF2959D3|Hspell:325877|h[Ember Blast]|h|r, |cFF2959D3|Hspell:328573|h[Blazing Surge]|h|r and the Reborn Phoenixes's |cFF2959D3|Hspell:328659|h[Smoldering Plumage]|h|r leave this pool.",difficultyIDs={14,15,16}},
			{id=21985,title="Section 27"},
			{id=21986,title="Section 28"},
			{id=21968,title="Section 26",body="$[!14,15,16\n\nOn Normal difficulty and higher, this also applies $341241s3 applications |cFF2959D3|Hspell:326430|h[Lingering Embers]|h|r, divided among all players hit.$]"},
			{id=22025,title="Section 27",difficultyIDs={14,15,16}},
			{id=22543,title="Section 29",difficultyIDs={17}},
			{id=22544,title="Section 29",difficultyIDs={14}},
			{id=22081,title="Section 29",body="$[!15,16\n\nOn Heroic difficulty and higher, |cFF2959D3|Hspell:328573|h[Blazing Surge]|h|r targets a random player's position rather than the primary target's position.$]",difficultyIDs={15,16}},
			{id=22090,title="Reborn Phoenix",body="$[!16On Mythic difficulty, the Reborn Phoenixes do not disappear when the Shade of Kael'thas is defeated.$]"},
			{id=22545,title="Section 35",difficultyIDs={17}},
			{id=22091,title="Section 35",difficultyIDs={14,15,16}},
			{id=22092,title="Section 36"},
			{id=21951,title="Ministers of Vice",body="As the fight progresses, Sire Denathrius's Ministers of Vice work to thwart the raid's attempts to save Kael'thas."},
