		sections={
			{id=21995,title="Overview",body="At full energy, Domina orders Brood Assassins concealed in |cFF2959D3|Hspell:332397|h[Shroudweb]|h|r to join the fight. Brood Assassins cast |cFF2959D3|Hspell:333406|h[Assassinate]|h|r until they are revealed from stealth."},
			{id=21998,title="Tank",body="$bullet;|cFF2959D3|Hspell:332313|h[Brood Assassins]|h|r cast |cFF2959D3|Hspell:333406|h[Assassinate]|h|r until they are revealed.\n\n$bullet;|cFF2959D3|Hspell:325552|h[Cytotoxic Slash]|h|r greatly increases damage taken by |cFF2959D3|Hspell:333406|h[Assassinate]|h|r and |cFF2959D3|Hspell:325551|h[Venomblades]|h|r."},
			{id=21996,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:332313|h[Brood Assassins]|h|r cast |cFF2959D3|Hspell:333406|h[Assassinate]|h|r until they are revealed.\n\n$bullet;Beware of nearby allies when targeted by |cFF2959D3|Hspell:325245|h[Shadow Ambush]|h|r."},
			{id=21997,title="Healer",body="$bullet;|cFF2959D3|Hspell:333406|h[Assassinate]|h|r inflicts heavy damage over time.\n\n$bullet;|cFF2959D3|Hspell:325552|h[Cytotoxic Slash]|h|r greatly increases damage taken by |cFF2959D3|Hspell:333406|h[Assassinate]|h|r and |cFF2959D3|Hspell:325551|h[Venomblades]|h|r.\n\n$bullet;Beware of your nearby allies when targeted by |cFF2959D3|Hspell:325245|h[Shadow Ambush]|h|r."},
			{id=22274,title="Brood Assassins",body="Brood Assassins join the encounter concealed within |cFF2959D3|Hspell:332397|h[Shroudweb]|h|r until revealed by players."},
