	[2426]={
		encounterID=2426,
		instanceID=1190,
		order=7,
		name="The Council of Blood",
		lore="The Council of Blood presides over courtly functions in Revendreth. Castellan Niklaus is a strict military commander with an indomitable will and impenetrable armor. Lord Stavros, a foppish dandy, leads the court in dance but is also deadly with his blades. Baroness Frieda wields powerful anima magics and commands the dredger wait staff--along with the respect of the entire court.",
		dungeonEncounterID=2412,
		uiMapID=1750,
