		sections={
			{id=22172,title="Overview",body="Over the course of the encounter the Hungering Destroyer gains energy.  Upon reaching 100 energy, the Hungering Destroyer casts |cFF2959D3|Hspell:334522|h[Consumes]|h|r attempting to devour all nearby life energy."},
			{id=22403,title="Tanks",body="$bullet; Coordinate with your co-tank to manage |cFF2959D3|Hspell:332295|h[Growing Hunger]|h|r.\n$bullet; Move away from the Hungering Destroyer when it casts |cFF2959D3|Hspell:334522|h[Consume]|h|r.",difficultyIDs={14,15,16}},
			{id=22404,title="Healers",body="$bullet; |cFF2959D3|Hspell:329298|h[Gluttonous Miasma]|h|r prevents all healing received by afflicted targets but siphons health from afflicted targets' nearby allies.\n$bullet; Position yourself to avold hitting other players when targeted by |cFF2959D3|Hspell:334266|h[Volatile Ejection]|h|r.\n$bullet; Move away from the Hungering Destroyer when it casts |cFF2959D3|Hspell:334522|h[Consume]|h|r.",difficultyIDs={14,15,16}},
			{id=22405,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:329298|h[Gluttonous Miasma]|h|r prevents all healing received by afflicted targets but siphons health from afflicted targets' nearby allies.\n$bullet; Position yourself to avold hitting other players when targeted by |cFF2959D3|Hspell:334266|h[Volatile Ejection]|h|r.\n$bullet; Move away from the Hungering Destroyer when it casts |cFF2959D3|Hspell:334522|h[Consume]|h|r.",difficultyIDs={14,15,16}},
			{id=22173,title="Tanks",body="$bullet; Coordinate with your co-tank to manage |cFF2959D3|Hspell:332295|h[Growing Hunger]|h|r.\n$bullet; Move away from the Hungering Destroyer when it casts |cFF2959D3|Hspell:334522|h[Consume]|h|r.",difficultyIDs={17}},
			{id=22174,title="Healers",body="$bullet; |cFF2959D3|Hspell:329298|h[Gluttonous Miasma]|h|r prevents all healing received by afflicted targets but siphons health from afflicted targets' nearby allies.\n$bullet; Position yourself to avold hitting other players when targeted by |cFF2959D3|Hspell:338614|h[Volatile Ejection]|h|r.\n$bullet; Move away from the Hungering Destroyer when it casts |cFF2959D3|Hspell:334522|h[Consume]|h|r.",difficultyIDs={17}},
