	[2429]={
		encounterID=2429,
		instanceID=1190,
		order=2,
		name="Huntsman Altimor",
		lore="Sire Denathrius seldom engages in the hunts himself, but Altimor makes certain the master has the finest beasts should he ever choose to indulge. Margore, Bargast, and Hecutis has been trained longer than most beasts have existed, and each is ready to deliver the Huntsman's wrath to any in his domain.",
		dungeonEncounterID=2418,
		uiMapID=1735,
		pin={x=0.6762,y=0.4948},
		difficultyIDs={14,15,16,17},
		npcIDs={165066,165067,169457,169458},
