		sections={
			{id=22463,title="Overview",body="Nurgash is a mighty warrior that hits hard with his fists. He can also call upon stone magics to blast an area with Earthen Blast, and will throw a Hail of Stones that hit all enemies that are far away from him, so stay close. He will grow in strength over time with Hardened Muck, and may strike very hard by the end of the battle."},
			{id=22464,title="Damage Dealers",body="$bullet;Avoid being hit by |cFF2959D3|Hspell:338864|h[Earthen Blast]|h|r.\n$bullet;Stay close to Nurgash so you aren't squashed by his |cFF2959D3|Hspell:338867|h[Hail of Stones]|h|r."},
			{id=22465,title="Tanks",body="$bullet;Avoid being hit by |cFF2959D3|Hspell:338864|h[Earthen Blast]|h|r.\n$bullet;Save a defensive cooldown for |cFF2959D3|Hspell:338858|h[Stone Fist]|h|r."},
			{id=22466,title="Healers",body="$bullet;Avoid being hit by |cFF2959D3|Hspell:338864|h[Earthen Blast]|h|r.\n$bullet;Stay close to Nurgash so you aren't squashed by his |cFF2959D3|Hspell:338867|h[Hail of Stones]|h|r.\n$bullet;Nurgash's |cFF2959D3|Hspell:338863|h[Stone Stomp]|h|r deals high damage to the entire raid, be prepared to heal up afterwards."},
