	[2435]={
		encounterID=2435,
		instanceID=1193,
		order=1,
		name="The Tarragrue",
		lore="The Jailer's relentless beast, the Tarragrue, has stalked the halls of Torghast since its first spire was raised. Countless victims have felt their souls trampled to ash by this monstrosity, which now awaits the mortal champions breaching the threshold of the tower.",
		dungeonEncounterID=2423,
		uiMapID=1998,
		pin={x=0.545,y=0.493},
		difficultyIDs={14,15,16,17},
		npcIDs={152253,175611},
