	[2436]={
		encounterID=2436,
		instanceID=1194,
		order=3,
		name="Mailroom Mayhem",
		lore="Something has gone wrong at the Primary Office for Sending Things (P.O.S.T.). Dimensional portals are scattering deliveries and the automaton that runs the office is malfunctioning. If the chaos is not sorted soon, the whole city could go postal.",
		dungeonEncounterID=2424,
		uiMapID=1989,
		pin={x=0.3855,y=0.3916},
		difficultyIDs={2,8,23},
		npcIDs={175646},
		displayIDs={100722},
		loot={
