		instanceID=1194,
		order=1,
		name="Zo'phex the Sentinel",
		lore="To gain entry beyond the gilded gates of Tazavesh, all must pass the sentinel, Zo'phex. Obsessed with security, Zo'phex ensures any contraband is immediately incinerated along with anyone holding the offending items.",
		dungeonEncounterID=2425,
		uiMapID=1989,
