		instanceID=1193,
		order=3,
		name="The Nine",
		lore="The dark pact Sylvanas struck with the val'kyr forged her bond with the Jailer. Through the years, these winged sisters faithfully served the Dark Lady, even if it meant sacrificing themselves on her behalf. Now Sylvanas calls her nine val'kyr to fight for her one last time.",
		dungeonEncounterID=2429,
		uiMapID=1999,
		pin={x=0.4222,y=0.1927},
		difficultyIDs={14,15,16,17},
		npcIDs={139941,147254,178684},
