	[2440]={
		encounterID=2440,
		instanceID=1193,
		order=9,
		name="Kel'Thuzad",
		lore="The nefarious Kel'Thuzad awaits at the apex of the soul river, allowing the lich to draw upon an unlimited well of power. All his countless schemes and machinations have led to this final confrontation, where he has plotted the mortal champions' ultimate demise in service of his true master.",
