			{id=23448,title="Section 43"},
			{id=23449,title="Glacial Spike",body="Once summoned, the Glacial Spike loses 5% health every 2 sec. Upon death the spike erupts, causing Frozen Destruction."},
			{id=23450,title="Section 44",difficultyIDs={15,16}},
			{id=23770,title="Section 54",difficultyIDs={14,17}},
			{id=23198,title="Section 10",difficultyIDs={14,15,16}},
			{id=23781,title="Frostbound Devoted",body="These skeletal constructs move towards a random player and detonate if they reach them.",difficultyIDs={14,15,16}},
