			{id=23785,title="Section 53"},
			{id=23200,title="Section 12"},
			{id=22885,title="Stage Two: The Phylactery Opens",body="When Kel'Thuzad is defeated, the phylactery opens and restores him to life once more. While open, players can enter the phylactery to battle the last remnant of Kel'Thuzad's soul. It is during this time Kel'Thuzad uses March of the Forsaken to summon his minions to protect his exposed phylactery."},
			{id=23562,title="Section 53",difficultyIDs={14,15,16}},
			{id=23444,title="Section 39",difficultyIDs={14,15,17}},
			{id=23835,title="Section 58",body="$[!16\n\nIn Mythic difficulty, Kel'Thuzad starts with applications of |cFF2959D3|Hspell:352051|h[Necrotic Surge]|h|r.$]",difficultyIDs={16}},
			{id=23665,title="Section 52",difficultyIDs={15,16}},
			{id=23425,title="Section 22"},
			{id=23426,title="Section 20"},
			{id=23424,title="Unstoppable Abomination",body="The Unstoppable Abomination's unholy strength allows it to inflict punishing melee attacks."},
			{id=23428,title="Section 23"},
			{id=23423,title="Soul Reaver",body="Soul Reaver's periodically unleash Banshee's Cry."},
			{id=23429,title="Section 24",difficultyIDs={15,16}},
			{id=23788,title="Section 54",difficultyIDs={14,17}},
			{id=23860,title="Section 63",difficultyIDs={15,16}},
			{id=23431,title="Remnant of Kel'Thuzad",body="At 60% and 20% health, the Remnant of Kel'Thuzad attempts to destroy anyone reamining within the phylactery with Undying Wrath and interrupts Kel'Thuzad's cast of Vengeful Destruction."},
			{id=23606,title="Section 48",difficultyIDs={16}},
