	[2441]={
		encounterID=2441,
		instanceID=1193,
		order=10,
		name="Sylvanas Windrunner",
		lore="With Oribos in peril, a desperate battle at the pinnacle of the Sanctum begins. Standing between the Jailer and the mortals who would stop him is Sylvanas Windrunner. With no masks left to wear, the Banshee Queen unleashes her full power to protect the Banished One while his ultimate plan unfolds.",
		dungeonEncounterID=2435,
		uiMapID=2002,
		pin={x=0.5166,y=0.5313},
		difficultyIDs={14,15,16,17},
		npcIDs={175732,177114,179687,180828},
		displayIDs={95032},
		loot={
			{itemID=186342,diffs={},faction=-1},
			{itemID=186353,diffs={},faction=-1},
			{itemID=186349,diffs={},faction=-1},
