	[2442]={
		encounterID=2442,
		instanceID=1193,
		order=2,
		name="The Eye of the Jailer",
		lore="When Azeroth was young, Odyn traded his eye to Mueh'zala to peer into the Shadowlands. Vain Odyn was deceived, for the Jailer twisted the Eye to serve his own ends. The Eye's unwavering gaze allows the Jailer to see all that transpires within his domain--and perhaps others as well.",
		dungeonEncounterID=2433,
		uiMapID=1999,
		pin={x=0.4671,y=0.9423},
