	[2443]={
		encounterID=2443,
		instanceID=1193,
		order=6,
		name="Painsmith Raznal",
		lore="Painsmith Raznal is a sadistic mastermind who has spent eons perfecting the deadly traps found in Torghast. He relishes the screams of his victims as a testament to his skill, listening with malignant delight as they echo through the tower's desolate halls.",
		dungeonEncounterID=2430,
