	[2444]={
		encounterID=2444,
		instanceID=1193,
		order=4,
		name="Remnant of Ner'zhul",
		lore="Intended to herald the Jailer's reign on Azeroth, the first Lich King, Ner'zhul, proved unworthy in his master's eyes. The last remnants of the fallen orc's twisted soul were encased in spiked shadowsteel, condemned to everlasting torment for his failure. All who cross his path will share in his suffering.",
		dungeonEncounterID=2432,
		uiMapID=2000,
		pin={x=0.8883,y=0.3569},
		difficultyIDs={14,15,16,17},
		npcIDs={175729},
		displayIDs={100681,101216,106461,106462,106463},
		loot={
