		},
		sections={
			{id=22904,title="Overview",body="The Remnant of Ner'zhul periodically manifests Orbs of Torment that inflict damage to all players until they're destroyed and thrown from the platform.\n\nAt 80%, 60%, and 30% health remaining, a piece of the armor encasing the Remnant of Ner'zhul shatters, increasing the intensity of |cFF2959D3|Hspell:350671|h[Aura of Spite]|h|r."},
			{id=22905,title="Tanks",body="$bullet;The Remnant of Ner'zhul uses |cFF2959D3|Hspell:349890|h[Suffering]|h|r when reaching 100 energy.\n$bullet;Orbs of Torment take reduced damage until struck with |cFF2959D3|Hspell:349890|h[Suffering]|h|r.\n$bullet;|cFF2959D3|Hspell:350469|h[Malevolence]|h|r knocks back all players from the position of the victim upon removal."},
			{id=22906,title="Damage Dealers",body="$bullet;Orbs of Torment take reduced damage until struck with |cFF2959D3|Hspell:349890|h[Suffering]|h|r.\n$bullet;|cFF2959D3|Hspell:350073|h[Torment]|h|r will inflict damage to all players until Orbs of Torment are thrown off the edge of the platform.\n$bullet;|cFF2959D3|Hspell:350469|h[Malevolence]|h|r knocks back all players from the position of the victim upon removal."},
			{id=22907,title="Healers",body="$bullet;|cFF2959D3|Hspell:350073|h[Torment]|h|r will inflict damage to all players until Orbs of Torment are thrown off the edge of the platform.\n$bullet;|cFF2959D3|Hspell:350469|h[Malevolence]|h|r knocks back all players from the position of the victim upon removal and inflicts signifcant damage to the raid.\n$bullet;|cFF2959D3|Hspell:350469|h[Malevolence]|h|r can be dispelled."},
			{id=23301,title="Orb of Torment",body="|cFF2959D3|Hspell:350073|h[Torments]|h|r players until it is carried to the edge of the platform and thrown off."},
			{id=23739,title="Section 15"},
			{id=23303,title="Section 9"},
			{id=23628,title="Section 14"},
			{id=23575,title="Section 22",body="$[!16\n\nIn Mythic difficulty, each of the piece of shattered armor drops to the ground and duplicates one of the Remnant of Ner'zhul's spell casts.$]"},
			{id=23765,title="Helm of Suffering",body="At 80% health remaining, the Helm of Suffering drops to the ground and will duplicate casts of |cFF2959D3|Hspell:349890|h[Suffering]|h|r.",difficultyIDs={16}},
			{id=23766,title="Gauntlet of Malice",body="At 60% health remaining, the Gauntlet of Malice drops to the ground and will duplicate casts of |cFF2959D3|Hspell:350076|h[Grasp of Malice]|h|r.",difficultyIDs={16}},
			{id=23767,title="Rattlecage of Agony",body="At 30% health remaining, the Rattlecage of Agony drops to the ground and will duplicate casts of |cFF2959D3|Hspell:350469|h[Malevolence]|h|r.",difficultyIDs={16}},
