		sections={
			{id=22910,title="Overview",body="As Dormazain inflicts |cFF2959D3|Hspell:350217|h[Torment]|h|r to Garrosh Hellscream, he gains energy. Upon reaching 100 energy, Dormazain performs |cFF2959D3|Hspell:349985|h[Tormented Eruptions]|h|r."},
			{id=22912,title="Damage Dealers",body="$bullet;Snapping all |cFF2959D3|Hspell:348985|h[Warmonger Shackles]|h|r binding Garrosh interrupts |cFF2959D3|Hspell:351946|h[Hellscream]|h|r.\n$bullet;Mawsworn Agonizers cast |cFF2959D3|Hspell:351779|h[Agonizing Nova]|h|r and become more powerful if allowed to reach 100 energy or Garrosh, gaining |cFF2959D3|Hspell:350650|h[Defiance]|h|r.\n$bullet;|cFF2959D3|Hspell:350648|h[Brand of Torment]|h|r inflicts damage to allies and Mawsworn."},
			{id=22913,title="Healers",body="$bullet;Snapping all |cFF2959D3|Hspell:348985|h[Warmonger Shackles]|h|r binding Garrosh will interrupt |cFF2959D3|Hspell:351946|h[Hellscream]|h|r.\n$bullet;|cFF2959D3|Hspell:349985|h[Tormented Eruptions]|h|r inflicts heavy damage.\n$bullet;|cFF2959D3|Hspell:350648|h[Brand of Torment]|h|r inflicts damage to allies and Mawsworn."},
			{id=22911,title="Tanks",body="$bullet;Snapping all |cFF2959D3|Hspell:348985|h[Warmonger Shackles]|h|r binding Garrosh interrupts |cFF2959D3|Hspell:351946|h[Hellscream]|h|r.\n$bullet;|cFF2959D3|Hspell:349985|h[Tormented Eruptions]|h|r inflicts heavy damage.\n$bullet;|cFF2959D3|Hspell:350422|h[Ruinblade]|h|r increases Physical damage taken."},
			{id=23285,title="Section 9"},
			{id=23286,title="Section 10"},
			{id=23288,title="Section 12"},
			{id=23333,title="Section 16"},
			{id=23415,title="Section 23",body="$[!15, 16\n\nIn Heroic difficulty and Mythic difficulties, Hellscream also causes all players to flee in fear.$]"},
			{id=23561,title="Section 31",difficultyIDs={15,16}},
			{id=23283,title="Section 7"},
			{id=23287,title="Section 11"},
			{id=23385,title="Section 19"},
			{id=23517,title="Mawsworn Overlord",body="Mawsworn Overlords move inexorably towards Garrosh, empowering nearby Mawsworn with |cFF2959D3|Hspell:353554|h[Infuse Defiance]|h|r. If allowed to reach Garrosh, Mawsworn Overlords empower all Mawsworn with |cFF2959D3|Hspell:354055|h[Defiant|r.",difficultyIDs={16}},
			{id=23518,title="Section 25"},
			{id=23520,title="Section 26"},
			{id=23541,title="Section 30"},
			{id=23289,title="Mawsworn Agonizer",body="Mawsworn Agonizers attempt to advance towards Garrosh to continue the task of tormenting him. Upon reaching Garrosh or 100 energy, the become suffused with |cFF2959D3|Hspell:350650|h[Defiance]|h|r, becoming immune to crowd control effects and dealing increased damage."},
			{id=23290,title="Section 14"},
			{id=23291,title="Section 15"},
			{id=22915,title="Garrosh Hellscream",body="|cFF2959D3|Hspell:350217|h[Torment]|h|r inflicted upon Garrosh unleashes waves of Anima. Any Mawsworn allowed to reach Garrosh become empowered with |cFF2959D3|Hspell:350650|h[Defiance]|h|r."},
			{id=23379,title="Section 18",difficultyIDs={15,16}},
			{id=23412,title="Section 20"},
			{id=23362,title="Section 17"},
			{id=23836,title="Section 25"},
		},
	},
	[2446]={
