		sections={
			{id=22916,title="Overview",body="Over the course of the encounter, the Guardian of the First Ones depletes its energy reserve. When the Guardian's Energy reaches 0 it activates |cFF2959D3|Hspell:352538|h[Purging Protocol]|h|r until it can link with an Energy Core."},
			{id=22917,title="Tanks",body="$bullet; Standing in |cFF2959D3|Hspell:352394|h[Radiant Energy]|h|r greatly reduces the effects of |cFF2959D3|Hspell:350455|h[Unstable Energy]|h|r.\n$bullet; The Guardian will activate |cFF2959D3|Hspell:352385|h[Energizing Link]|h|r while standing near an Energy Core.\n$bullet; The Guardian gains significant attack speed while |cFF2959D3|Hspell:352538|h[Purging Protocol]|h|r is active."},
			{id=22918,title="Damage Dealers",body="$bullet; Standing in |cFF2959D3|Hspell:352394|h[Radiant Energy]|h|r greatly reduces the effects of |cFF2959D3|Hspell:350455|h[Unstable Energy]|h|r.\n$bullet; |cFF2959D3|Hspell:356090|h[Threat Neutralization]|h|r inflicts substantial Arcane damage to the targeted player and nearby allies."},
			{id=22919,title="Healers",body="$bullet; Standing in |cFF2959D3|Hspell:352394|h[Radiant Energy]|h|r greatly reduces the effects of |cFF2959D3|Hspell:350455|h[Unstable Energy]|h|r.\n$bullet; |cFF2959D3|Hspell:352538|h[Purging Protocol]|h|r inflicts increasing Arcane damage to all players until the Guardian links with an Energy Core.\n$bullet; |cFF2959D3|Hspell:356090|h[Threat Neutralization]|h|r inflicts substantial Arcane damage to the targeted player and nearby allies."},
			{id=23271,title="Section 12"},
			{id=23473,title="Section 16"},
			{id=23474,title="Section 17"},
			{id=23635,title="Section 21",body="$[!16\n\nIn Mythic difficulty, the Guardian depletes 20 energy if Obliterate fails to hit at least 4 players.$]",difficultyIDs={15,16}},
			{id=23274,title="Section 10"},
			{id=23515,title="Section 17"},
			{id=23792,title="Section 20"},
			{id=23276,title="Section 13",body="$[!16 \n\nIn Mythic difficulty, striking an Energy Core with this effect restores energy.$]"},
			{id=23472,title="Section 18"},
			{id=23254,title="Energy Cores"},
