	[2447]={
		encounterID=2447,
		instanceID=1193,
		order=8,
		name="Fatescribe Roh-Kalo",
		lore="Once a fatescribe entrusted with Korthia's countless secrets, the Mawsworn seized Roh-Kalo and bound him to the Jailer's will. With Torghast's power at his disposal, Roh-Kalo seeks to author a new fate for the Shadowlands.",
