	[2448]={
		encounterID=2448,
		instanceID=1194,
		order=6,
		name="Hylbrande",
		lore="The theft of an ancient Titan artifact has awoken its guard: Hylbrande, Sword of the Keepers. Dismantle the myriad of security protocols at Hylbrand's command, or become permanent residents of the tomb.",
		dungeonEncounterID=2426,
		uiMapID=1997,
		pin={x=0.5904,y=0.4232},
		difficultyIDs={2,8,23},
		npcIDs={175663},
		displayIDs={70368,100495},
		loot={
			{itemID=185810,diffs={},faction=-1},
			{itemID=185803,diffs={},faction=-1},
			{itemID=185779,diffs={},faction=-1},
			{itemID=185788,diffs={},faction=-1},
			{itemID=185805,diffs={},faction=-1},
			{itemID=185790,diffs={},faction=-1},
			{itemID=185781,diffs={},faction=-1},
			{itemID=182105,diffs={},faction=-1},
			{itemID=182336,diffs={},faction=-1},
			{itemID=181373,diffs={},faction=-1},
			{itemID=180943,diffs={},faction=-1},
			{itemID=183501,diffs={},faction=-1},
			{itemID=183467,diffs={},faction=-1},
			{itemID=246275,diffs={},faction=-1},
			{itemID=246280,diffs={},faction=-1},
		},
		sections={
			{id=22996,title="Overview",body="Hylbrande attacks players with aid from Vault Purifiers as well as the Titan Vault's built in defenses.\n\nUpon reaching 100 energy, Hylbrande begins a |cFF2959D3|Hspell:346766|h[Sanitizing Cycle]|h|r. Players must acquire Bypass Codes and input them into the correct Security Panels to avoid certain death. The Titan Console reveals the code layout."},
			{id=22997,title="Damage Dealers",body="$bullet;|cFF2959D3|Hspell:346959|h[Purged by Fire]|h|r leaves behind purging fields that can make it dangerous to access panels.\n$bullet;Vault Purifiers aid Hylbrande with |cFF2959D3|Hspell:347015|h[Empowered Defense]|h|r, and lock out Security Panels during |cFF2959D3|Hspell:346766|h[Sanitizing Cycle]|h|r with |cFF2959D3|Hspell:347958|h[Keeper's Protection]|h|r."},
			{id=22998,title="Healer",body="$bullet;|cFF2959D3|Hspell:346959|h[Purged by Fire]|h|r will focus damage on a player.\n$bullet;Players are likely to be very spread out during |cFF2959D3|Hspell:346766|h[Sanitizing Cycle]|h|r."},
			{id=22999,title="Tank",body="$bullet;|cFF2959D3|Hspell:347094|h[Titanic Crash]|h|r hits all players in front of Hylbrande.\n$bullet;Vault Purifiers aid Hylbrande with |cFF2959D3|Hspell:347015|h[Empowered Defense]|h|r, and lock out Security Panels during |cFF2959D3|Hspell:346766|h[Sanitizing Cycle]|h|r with |cFF2959D3|Hspell:347958|h[Keeper's Protection]|h|r."},
			{id=24842,title="Section 16"},
			{id=23000,title="Section 5"},
			{id=23001,title="Section 6"},
			{id=23002,title="Section 7"},
			{id=23014,title="Section 14"},
			{id=23003,title="Sanitizing Cycle",body="Hylbrande channels titan power from the chamber to purge all unauthorized life forms as a safety measure, becoming immune to damage and filling the room with a |cFF2959D3|Hspell:346828|h[Sanitizing Field]|h|r.\n\nBypass Codes appear near Hylbrande and can be picked up by players and deposited into nearby Security Panels.\n\nPlayers can access the Titan Console in the rear of the chamber to gain |cFF2959D3|Hspell:346427|h[Titanic Insight]|h|r, allowing them to confirm where each code must be placed."},
			{id=24760,title="Section 15"},
			{id=23758,title="Section 14"},
			{id=23004,title="Vault Purifier",body="Vault Purifiers join the fight two at a time as Hylbrande calls for them."},
			{id=23005,title="Section 9"},
			{id=23549,title="Section 19"},
			{id=23550,title="Section 20"},
		},
	},
