		sections={
			{id=23015,title="Overview",body="Timecap'n Hooktail commands her infamous pirate ship, The Hourglass, to |cFF2959D3|Hspell:347370|h[Cannon Barrage]|h|r the beach while she engages players in close combat.\n\nCorsair Brutes grapple from the deck to support their captain, but her |cFF2959D3|Hspell:347149|h[Infinite Breath]|h|r is deadly for players and Corsairs alike."},
			{id=23016,title="Damage Dealers",body="$bullet;Hooktail's |cFF2959D3|Hspell:347149|h[Infinite Breath]|h|r can damage and stun players, but it also kills Corsair Brutes instantly.\n$bullet;|cFF2959D3|Hspell:347370|h[Cannon Barrage]|h|r inflicts heavy damage to players in the impact area."},
			{id=23017,title="Healer",body="$bullet;|cFF2959D3|Hspell:352345|h[Anchor Shot]|h|r inflicts heavy damage to a random player.\n$bullet;|cFF2959D3|Hspell:347370|h[Cannon Barrage]|h|r inflicts heavy damage to players in the impact area."},
			{id=23018,title="Tank",body="$bullet;Hooktail's |cFF2959D3|Hspell:347149|h[Infinite Breath]|h|r can damage and stun players, but it also kills Corsair Brutes instantly.\n$bullet;|cFF2959D3|Hspell:347370|h[Cannon Barrage]|h|r inflicts heavy damage to players in the impact area."},
