			{id=23834,title="Section 13"},
			{id=23833,title="Corsair Brute",body="Members of Timecap'n Hooktail's crew grapple from the deck to attack players, but they're unaccustomed to her dragon form and vulnerable to her |cFF2959D3|Hspell:347149|h[Infinite Breath]|h|r."},
