	[2456]={
		encounterID=2456,
		instanceID=1192,
		order=5,
		name="Mor'geth, Tormentor of the Damned",
		lore="Among the countless minions of the Jailer, few relish their twisted work as intently as the vile Mor'geth. Obsessed with breaking the will of any soul unfortunate enough to fall into his grasp, Mor'geth maintains an iron grip upon the battlefield, ensuring that any misstep will be his opponent's last.",
		dungeonEncounterID=2496,
		pin={x=0.5,y=0.5},
