	[2458]={
		encounterID=2458,
		instanceID=1195,
		order=1,
		name="Vigilant Guardian",
		lore="This eternal guardian lies in wait, keeping a timeless vigil over the entrance to the Sepulcher of the First Ones.",
		dungeonEncounterID=2512,
		uiMapID=2047,
		pin={x=0.5327,y=0.52},
		difficultyIDs={14,15,16,17},
		npcIDs={180773,184522},
		displayIDs={98789,102474,103101,103105,104830},
		loot={
			{itemID=189771,diffs={},faction=-1},
