		sections={
			{id=24296,title="Overview",body="As combat unfolds, Lihuvim accumulates protoform energy.  Upon reaching 100 energy, Lihuvim casts |cFF2959D3|Hspell:363130|h[Synthesize]|h|r which allows nearby protoform lattices to be destroyed.  Any remaining lattices are transformed into Protoform Automa when the synthesis completes."},
			{id=24297,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Unstable Motes in its area of effect.\n$bullet; Guardian Automa will repeatedly attempt to |cFF2959D3|Hspell:365257|h[Form Sentry Automa]|h|r while they remain on the battlefield.",difficultyIDs={7,17}},
			{id=24755,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Unstable Motes in its area of effect.\n$bullet; |cFF2959D3|Hspell:363088|h[Cosmic Shift]|h|r pushes players away.\n$bullet; Guardian Automa will repeatedly attempt to |cFF2959D3|Hspell:365257|h[Form Sentry Automa]|h|r while they remain on the battlefield.",difficultyIDs={14,15}},
			{id=24756,title="Damage Dealers",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Unstable Motes in its area of effect.\n$bullet; |cFF2959D3|Hspell:363088|h[Cosmic Shift]|h|r displaces players towards or away from Lihuvim.\n$bullet; Guardian Automa will repeatedly attempt to |cFF2959D3|Hspell:365257|h[Form Sentry Automa]|h|r while they remain on the battlefield.",difficultyIDs={16}},
			{id=24757,title="Healers",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Unstable Motes in its area of effect.\n$bullet; |cFF2959D3|Hspell:363538|h[Protoform Radiance]|h|r periodically inflicts heavy Cosmic damage to all players.\n$bullet; |cFF2959D3|Hspell:364092|h[Degenerate]|h|r periodically inflicts heavy Cosmic damage.",difficultyIDs={7,17}},
			{id=24301,title="Healers",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Unstable Motes in its area of effect.\n$bullet; |cFF2959D3|Hspell:363538|h[Protoform Radiance]|h|r inflicts ramping Cosmic damage over its duration.\n$bullet; |cFF2959D3|Hspell:364092|h[Degenerate]|h|r inflicts heavy periodic damage over time.",difficultyIDs={14,15,16}},
			{id=24758,title="Tanks",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Genesis Motes in its area of effect, and increases the target's Physical damage taken.\n$bullet; |cFF2959D3|Hspell:363018|h[Protoform Cascade]|h|r inflicts damage to all players in a circle around Lihuvim.",difficultyIDs={7,17}},
			{id=24305,title="Tanks",body="$bullet; |cFF2959D3|Hspell:363681|h[Deconstructing Blast]|h|r destroys Genesis Motes in its area of effect, and increases the target's Physical damage taken.\n$bullet; |cFF2959D3|Hspell:363018|h[Protoform Cascade]|h|r inflicts damage to all players in a circle around Lihuvim.\n$bullet; |cFF2959D3|Hspell:368027|h[Resonance]|h|r inflicts heavy damage and applies vulnerabillities to all players hit by the blast.",difficultyIDs={14,15,16}},
