	[2468]={
		encounterID=2468,
		instanceID=1192,
		order=6,
		name="Antros",
		lore="Antros serves as the guardian to the treasures of Antecedent Isle. The Jailer's forces seek to use it in its' newly dominated form to unearth the isle's secrets to further desecrate Zereth Mortis.",
		dungeonEncounterID=2550,
		pin={x=0.5,y=0.5},
